function update(value) {
  let countdownInput = scriptProperties.countdown;
  let currentDate = new Date();
  let countdownDate;
  let isRepeating = false;

  if (!countdownInput) {
    value = `[${scriptProperties.name}]`;
    thisScene.getLayer('discription2').text = ``;
    return value;
  }

   countdownInput = countdownInput.replace(/[\/]/g, "-");
  let parts = countdownInput.split('-'); // YYYY-MM-DD, YYYY/MM/DD, MM-DD or MM/DD expected

  if (parts.length === 2) {
    // MM-DD format (repeat every year)
    let month = parseInt(parts[0], 10) - 1;
    let day = parseInt(parts[1], 10);
    let year = currentDate.getFullYear();
    countdownDate = new Date(year, month, day);
    isRepeating = true;

    // If the date has already passed this year, set it to next year
    if (
      countdownDate.getMonth() < currentDate.getMonth() ||
      (countdownDate.getMonth() === currentDate.getMonth() &&
        countdownDate.getDate() < currentDate.getDate())
    ) {
      countdownDate.setFullYear(year + 1);
    }
  } else {
    // Standard YYYY-MM-DD format
    countdownDate = new Date(countdownInput);
  }

  let difference = countdownDate.getTime() - currentDate.getTime();
  let daysRemaining = Math.ceil(difference / (1000 * 60 * 60 * 24));

  let discription = thisScene.getLayer('discription2');

  if (daysRemaining === 0) {
    value = `>> [${scriptProperties.name}]\nTODAY`;
    discription.text = isRepeating ? `COUNTDOWN [REP]` : `COUNTDOWN`;
  } else if (difference < 0 && parts.length === 3) {
    // Only count up if a full date (YYYY-MM-DD) was provided
    let daysPassed = Math.floor(-difference / (1000 * 60 * 60 * 24));
    value = `[${scriptProperties.name}]\n${daysPassed} DAYS PASSED`;
    discription.text = `COUNT-UP`;
  } else {
    value = `[${scriptProperties.name}]\n${daysRemaining} DAYS LEFT`;
    discription.text = isRepeating ? `COUNTDOWN [REP]` : `COUNTDOWN`;
  }

  return value;
}

